function validate([buckets, loss]) {
  if (buckets.length < 1 || buckets.length > 100000) return 'buckets needs 1 to 10^5 values.';
  if (buckets.some(v => !Number.isInteger(v) || v < 0 || v > 100000)) return 'Each bucket holds a whole number from 0 to 10^5.';
  if (!Number.isInteger(loss) || loss < 0 || loss > 99) return 'loss is a whole number from 0 to 99.';
  return null;
}

