function equalizeWater(buckets, loss) {
  const keep = (100 - loss) / 100;
  let low = Math.min(...buckets);
  let high = Math.max(...buckets);

  while (high - low > 1e-6) {
    const level = (low + high) / 2;
    let spare = 0;
    let needed = 0;
    for (const water of buckets) {
      if (water > level) {
        spare += (water - level) * keep;
      } else {
        needed += level - water;
      }
    }
    if (spare >= needed) {
      low = level;
    } else {
      high = level;
    }
  }
  return low;
}

