function equalizeWater(buckets, loss) {
  // Solve the balance equation exactly on each stretch between consecutive sorted values.
  const keep = (100 - loss) / 100;
  const sorted = [...buckets].sort((a, b) => a - b);
  const n = sorted.length;
  const total = sorted.reduce((sum, v) => sum + v, 0);
  let below = 0;
  for (let k = 1; k <= n; k++) {
    // Assume the k smallest buckets receive water and the others give it away.
    below += sorted[k - 1];
    const above = total - below;
    // keep * (above - (n - k) * x) = k * x - below
    const x = (keep * above + below) / (k + keep * (n - k));
    const upper = k < n ? sorted[k] : Infinity;
    if (x >= sorted[k - 1] - 1e-9 && x <= upper + 1e-9) return x;
  }
  return sorted[0];
}

