function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  const top = size === 'large' || rand() < 0.3 ? 100000 : [1, 10, 50][Math.floor(rand() * 3)];
  const lossChoice = rand();
  const loss = lossChoice < 0.15 ? 0 : lossChoice < 0.3 ? 99 : Math.floor(rand() * 100);
  const buckets = [];
  if (size === 'small' && rand() < 0.15) {
    const same = Math.floor(rand() * (top + 1));
    for (let i = 0; i < n; i++) buckets.push(same);
  } else {
    for (let i = 0; i < n; i++) buckets.push(Math.floor(rand() * (top + 1)));
  }
  return [buckets, loss];
}
